 const FuncOrderChecker = require('./func-order')
 const ImportsOnTopChecker = require('./imports-on-top')
+const BaseChecker = require('./../base-checker')
 const VisibilityModifierOrderChecker = require('./visibility-modifier-order')

+const ruleId = 'ordering'
+const meta = {
+  type: 'order',
+  docs: {
+    description: 'Ordering of contract elements is incorrect.',
+    category: 'Style Guide Rules'
+  },
+  isDefault: false,
+  recommended: false,
+  defaultSetup: 'warn',
+  schema: null
+}
+
+const elementOrder = [
+  'EventDefinition',
+  'StructDefinition',
+  'EnumDefinition',
+  'StateVariableDeclaration',
+  'ModifierDefinition',
+  'FunctionDefinition'
+]
+
+function orderIndex(type) {
+  if (type === 'ConstructorDefinition') return elementOrder.indexOf('FunctionDefinition')
+  return elementOrder.indexOf(type)
+}
+
+class OrderingChecker extends BaseChecker {
+  constructor(reporter) {
+    super(reporter, ruleId, meta)
+  }
+
+  ContractDefinition(node) {
+    let previousType
+    let previousIndex = -1
+
+    for (const child of node.children || []) {
+      const currentIndex = orderIndex(child.type)
+      if (currentIndex === -1) continue
+
+      if (currentIndex < previousIndex) {
+        this.error(
+          child,
+          `Order of elements is incorrect, ${child.type} definition can not go after ${previousType} definition.`
+        )
+      }
+
+      previousType = child.type
+      previousIndex = currentIndex
+    }
+  }
+}
+
 module.exports = function order(reporter, tokens) {
   return [
     new FuncOrderChecker(reporter),
     new ImportsOnTopChecker(reporter),
+    new OrderingChecker(reporter),
     new VisibilityModifierOrderChecker(reporter, tokens)
   ]
 }

