+}
+
+class OrderingChecker extends BaseChecker {
+  constructor(reporter) {
+    super(reporter, ruleId, meta)
+  }
+
+  ContractDefinition(node) {
+    let lastOrder = -1
+
+    for (const child of node.subNodes || []) {
